@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');
/* =========================================================
   ROOT CONTAINER - WIDER
   ========================================================= */

:root {
  --phosphor-main: #33ff00;
  --phosphor-dim: #1a8000;
  --bg-color: #050a05;
}
#root > * {
  position: relative;
  z-index: 5;

}
#root {
  max-width: 1400px;
  margin: 0 auto;
  padding: 20px 40px;
  min-height: 100vh;
  border-left: 2px solid var(--phosphor-dim);
  border-right: 2px solid var(--phosphor-dim);
  position: relative;
}

/* =========================================================
   GLOBAL RESET
   ========================================================= */
* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background-color: var(--bg-color);
  color: var(--phosphor-main);
  font-family: 'VT323', monospace;
  font-size: 20px;
  height: 100%;
  width: 100%;
  overflow-x: hidden;

  /* phosphor bloom */
  text-shadow:
    0 0 1px var(--phosphor-main),
    0 0 6px rgba(51,255,0,0.45);
}

/* =========================================================
   PHOSPHOR DOT GRID (SHADOW MASK)
   ========================================================= */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9997;

  background-image:
    radial-gradient(
      rgba(51,255,0,0.04) 1px,
      transparent 1px
    );

  background-size: 4px 4px;
  opacity: 0.18;
  filter: blur(0.6px);
}
/* =========================================================
   SCANLINES + RGB BLEED
   ========================================================= */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9998;

  background:
    repeating-linear-gradient(
      to bottom,
      rgba(0,0,0,0.28),
      rgba(0,0,0,0.28) 1px,
      rgba(0,0,0,0) 2px
    ),
    linear-gradient(
      90deg,
      rgba(255,0,0,0.05),
      rgba(0,255,0,0.02),
      rgba(0,0,255,0.05)
    );

  background-size: 100% 3px, 4px 100%;
  animation: crt-flicker 0.14s infinite;
}

@keyframes crt-flicker {
  0% { opacity: 0.94; }
  50% { opacity: 1; }
  100% { opacity: 0.96; }
}

/* =========================================================
   CRT FALL-OFF + CURVATURE
   ========================================================= */


#root::before {
  content: "";
  position: absolute;
