  pointer-events: none;
  z-index: 1;
  background:
    linear-gradient(rgba(51,255,0,0.45), transparent 60%),
    repeating-linear-gradient(to right, rgba(51,255,0,0.3), rgba(51,255,0,0.3) 1px, transparent 1px, transparent 48px),
